57: void *SDL_LoadFunction(void *handle, const char *name)
58: {
59:     void *symbol = dlsym(handle, name);
60:     if (!symbol) {
61:         /* prepend an underscore for platforms that need that. */
62:         SDL_bool isstack;
63:         size_t len = SDL_strlen(name) + 1;
64:         char *_name = SDL_small_alloc(char, len + 1, &isstack);
65:         _name[0] = '_';
66:         SDL_memcpy(&_name[1], name, len);
67:         symbol = dlsym(handle, _name);
68:         SDL_small_free(_name, isstack);
69:         if (!symbol) {
70:             SDL_SetError("Failed loading %s: %s", name,
71:                          (const char *)dlerror());
72:         }
